const {fitDataAsync, OPTIMIZERS} = DataScience;
const dimensions = 50;
const latentDimensions = 64;
const K = 10;
const epochs = 1000;
const batchSize = 100;
const status = document.createElement("div");
status.style.whiteSpace = "normal";
status.textContent = "Loading MNIST...";
const images = IO.paintMNIST(Array.from({length: K}, () => new Float32Array(28 * 28)), 5);
const ui = IO.UI(
    {type: "canvas", value: () => status},
    {type: "canvas", value: () => images},
);

const initialize = async () => {
    const samples = await IO.loadMNIST();
    if (samples.length <= dimensions) throw new Error("At least 51 MNIST images are required");
    status.textContent = "Computing PCA...";
    await new Promise(resolve => setTimeout(resolve, 0));
    const pca = PCA.new(samples, dimensions);
    const coordinates = samples.map(sample => pca.proj(sample));
    if (coordinates.some(point => point.some(value => !Number.isFinite(value)))) {
        throw new Error("PCA produced non-finite coordinates");
    }

    status.textContent = "Preparing autoencoder...";
    await new Promise(resolve => setTimeout(resolve, 0));
    const autoencoder = NeuralNet.builder()
        .input(dimensions)
        .layer(latentDimensions)
        .layer(dimensions, NeuralNet.ACTIVATIONS.linear)
        .build();
    console.log(`Training autoencoder on ${coordinates.length} PCA projections with random mini-batches of ${Math.min(batchSize, coordinates.length)}.`);
    const {theta} = await fitDataAsync(coordinates, coordinates, autoencoder.model, {
        epochs,
        batch: batchSize,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.01}),
        continuationEvery: 10,
        continuationFn: ({epoch, loss}) => {
            const progress = `Training autoencoder: ${epoch + 1}/${epochs} (mini-batch loss ${loss.toFixed(2)})`;
            status.textContent = progress;
            console.log(progress);
        },
    });

    status.textContent = "Clustering encoded images...";
    await new Promise(resolve => setTimeout(resolve, 0));
    const encoder = NeuralNet.builder().input(dimensions).layer(latentDimensions).build();
    encoder.setWeights(theta);
    const decoder = NeuralNet.builder().input(latentDimensions).layer(dimensions, NeuralNet.ACTIVATIONS.linear).build();
    const decoderWeights = {};
    for (const key of Object.keys(decoder.weightsMap)) {
        const source = key.replace(/^W0_/, "W1_").replace(/^b0_/, "b1_");
        if (!(source in theta)) throw new Error(`Missing trained decoder weight: ${source}`);
        decoderWeights[key] = theta[source];
    }
    decoder.setWeights(decoderWeights);
    const latentPoints = coordinates.map(point => encoder.eval(point));
    if (latentPoints.some(point => point.some(value => !Number.isFinite(value)))) {
        throw new Error("Encoder produced non-finite coordinates");
    }
    const kmeans = Kmeans.new(latentPoints, K, {maxIterations: 20}).fit();
    const centers = Array.from({length: K}, () => new Array(latentDimensions).fill(0));
    const counts = new Array(K).fill(0);
    for (const point of latentPoints) {
        const cluster = kmeans.predictIndex(point);
        counts[cluster]++;
        for (let i = 0; i < latentDimensions; i++) centers[cluster][i] += point[i];
    }
    const reconstructions = centers.map((center, cluster) => {
        if (counts[cluster] === 0) {
            console.warn(`Cluster ${cluster} is empty`);
            return new Float32Array(28 * 28);
        }
        const latent = center.map(value => value / counts[cluster]);
        const input = Object.fromEntries(latent.map((value, i) => [`x_${i}`, value]));
        const decoded = decoder.compiledNN({...input, ...decoder.weightsMap});
        if (decoded.some(value => !Number.isFinite(value))) throw new Error(`Cluster ${cluster} produced non-finite coordinates`);
        return new Float32Array(pca.gen(decoded).toArray());
    });
    images.update(reconstructions);
    status.textContent = "Showing decoded cluster centers.";
    console.log("Autoencoder clustering complete.");
};
setTimeout(() => {
    initialize().catch(error => {
        console.error("Could not initialize autoencoder clustering:", error);
        status.textContent = `Could not initialize autoencoder clustering: ${error.message}`;
    });
}, 0);
ui;
